/// Address the oracle gave buffer argument `i` (documented layout: 4 MB apart from 0x20000000, the region ends
/// at the end of its last page, the argument is region start + off).
fn addr(c: &Case, i: usize) -> u64 {
    let size = c.buf(i).len() as u64;
    0x2000_0000 + (i as u64) * 0x40_0000 + ((size + 0xfff) & !0xfff) - size + c.buf_off(i) as u64
}

fn run(name: &str, f: impl Fn(&Case) -> Outcome) {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..").join("vectors").join(format!("{}.vec", name));
    let vf = load(&path).unwrap();
    let rep = check(&vf, f);
    println!("PARITY {} total={} compared={} skipped={} failed={}", rep.name, rep.total, rep.compared, rep.skipped, rep.failed);
    lift_b::cov::report(name);
    rep.assert_ok(450);
}

